create or replace function public.ege_word_version_autorisee(p_commande uuid,p_version uuid) returns text language plpgsql security definer set search_path='' as $$ declare path text; begin if auth.uid() is null then raise exception 'Connexion obligatoire'; end if; select v.chemin_fichier into path from public.ege_versions_word v join public.ege_commandes c on c.id=v.commande_id where c.id=p_commande and v.id=p_version and c.acheteur_id=auth.uid() and c.statut='livre' and c.date_confirmation is not null and c.date_livraison is not null; if path is null then raise exception 'Version non autorisee'; end if; return path; end $$; revoke all on function public.ege_word_version_autorisee(uuid,uuid) from public,anon; grant execute on function public.ege_word_version_autorisee(uuid,uuid) to authenticated;;

